  const gy = (dy1/d1)*pull*0.4 + (dy2/d2)*pull*0.3;
  const fx = Math.sin(y*0.012+t*0.5)*8 + Math.cos(x*0.008+t*0.3)*6;
  const fy = Math.cos(x*0.012-t*0.4)*8 + Math.sin(y*0.01+t*0.35)*6;
  const sx = x + gx + fx, sy = y + gy + fy;
  const src = [
    [160+Math.sin(t*0.6)*100, 80+Math.cos(t*0.4)*50, 0.1, 2.0],
    [320+Math.cos(t*0.5)*100, 160+Math.sin(t*0.7)*50, 0.12, 1.7],
    [240+Math.sin(t*0.3+2)*140, 120+Math.cos(t*0.5+1)*90, 0.08, 2.3],
    [120+Math.cos(t*0.8+1)*80, 180+Math.sin(t*0.6+3)*60, 0.14, 1.5],
    [360+Math.sin(t*0.4+4)*90, 60+Math.cos(t*0.9+2)*70, 0.09, 2.6],
    [240+Math.cos(t*0.35+5)*120, 200+Math.sin(t*0.55)*80, 0.11, 1.9],
    [80+Math.sin(t*0.7+3)*70, 40+Math.cos(t*0.5+4)*50, 0.13, 2.1],
    [400+Math.cos(t*0.6+2)*60, 200+Math.sin(t*0.8+1)*70, 0.07, 2.4]
  ];
  let aS = 0, iS = 0;
  for (const [sX, sY, f, sp] of src) {
    const d = Math.sqrt((sx-sX)**2 + (sy-sY)**2);
    const potential = 1/(d*0.02+1);
    const kinetic = Math.sin(d*f - t*sp);
    aS += kinetic * potential;
    iS += Math.sin(d*f*0.7 + t*sp*0.6 + 1.5) * potential;
  }
  const act = aS/8, inh = iS/8;
  const bg = (Math.sin(sx*0.04+sy*0.025+t*0.8) + Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const dist = Math.sqrt((sx-cx)**2 + (sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
