  const potential2 = Math.sin(dist*0.03-t*0.5)*Math.cos(ang*2+t*0.3);
  const raw = act - inh*0.65 + bg*0.25 + spiral + potential2*0.2;
  const reaction = Math.tanh(raw*3.0);
