    [0,200,255],[0,255,200],[100,255,100],
    [255,255,50],[255,180,0],[255,60,80],
    [255,0,180],[180,0,255],[80,0,180],[0,0,0]
  ];
  const idx = v*(neon.length-1), i = Math.min(idx|0, neon.length-2), f = idx-i;
  let r = neon[i][0]+(neon[i+1][0]-neon[i][0])*f;
  let g = neon[i][1]+(neon[i+1][1]-neon[i][1])*f;
  let b = neon[i][2]+(neon[i+1][2]-neon[i][2])*f;
  r = r*edge + glowPow*r*0.8;
  g = g*edge + glowPow*g*1.0;
